        "overview": "to부정사가 진주어로 쓰일 때 주어 자리에 가주어 It을 둡니다. to부정사의 주체를 밝히는 의미상 주어는 일반적으로 [for + 목적격]을 쓰지만, kind, polite, generous, rude, foolish, wise 등 사람의 인품이나 태도를 나타내는 형용사 뒤에는 [of + 목적격]을 씁니다.",
